import numpy as np, torch, model
net = model.load()
w=torch.tensor(np.load('contrast_c1_out_act_k10.npy')); b=-22.3573
st=np.load('sim_state.npy'); c=st[:,0].astype(np.float32); xi=st[:,1:].astype(np.float32)
a0=np.asarray(model.decode(net,xi,c)); 
state={'k':0,'dv':None,'hi':11}
def hook(m,inp,out):
    k=state['k']; state['k']+=1
    if state['dv'] is None or k>=state['hi']: return out
    g=((inp[0]@w+b)>0).float().unsqueeze(-1)
    return out+g*state['dv']
h=net.out.register_forward_hook(hook)
def run(dv,hi=11):
    state['k']=0; state['dv']=torch.tensor(dv,dtype=torch.float32); state['hi']=hi
    return np.asarray(model.decode(net,xi,c))
tgtc=np.array([2.3,1.46])
T=np.linalg.norm(a0-tgtc,axis=1)<1.5
print('orig in region',T.mean())
other=a0[~T]
def nn(x):
    return np.sqrt(((x[:,None]-other[None])**2).sum(-1)).min(1)
base_nn=np.median(nn(a0[~T][:500]+1e-9))
for ang in range(0,360,45):
  for mag in [1.5,3,5]:
    u=np.array([np.cos(np.radians(ang)),np.sin(np.radians(ang))])
